import {
  Box,
  Stack,
  Typography,
} from "@mui/material";

import {
  CompareArrowsRounded,
  CalendarMonthRounded,
} from "@mui/icons-material";

import {
  Area,
  AreaChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

import {
  ForecastFilters,
  ForecastScenarioRecord,
} from "../types/forecast.types";

import {
  useForecastScenarioData,
} from "../hooks/useForecast";


interface ScenarioTrendChartProps {
  filters: ForecastFilters;
}


interface ScenarioChartPoint {
  date: string;
  baseline: number;
  scenario: number;
}


const ScenarioTrendChart = ({
  filters,
}: ScenarioTrendChartProps) => {

  const {
    data,
    isLoading,
    isError,
  } = useForecastScenarioData();


  /*
   * ---------------------------------------------------------
   * LABELS
   * ---------------------------------------------------------
   */

  const getMetricLabel = (): string => {
    switch (filters.metric) {
      case "burn":
        return "Burn";

      case "supply":
        return "Supply";

      case "stockpile":
        return "Stockpile";

      default:
        return "Forecast";
    }
  };


  const getMetricUnit = (): string => {
    if (
      filters.metric ===
      "stockpile"
    ) {
      return "tonnes";
    }

    if (
      filters.horizon ===
      "daily"
    ) {
      return "t/day";
    }

    return "tonnes";
  };


  const getScenarioLabel = (
    scenarioId: string
  ): string => {

    switch (scenarioId) {

      case "weather_hot_dry":
        return "Hot & Dry";

      case "weather_hot_wet":
        return "Hot & Wet";

      case "weather_cold_dry":
        return "Cold & Dry";

      case "weather_cold_wet":
        return "Cold & Wet";

      case "actual":
        return "Baseline";

      default:
        return scenarioId;
    }
  };


  /*
   * ---------------------------------------------------------
   * METRIC VALUE
   * ---------------------------------------------------------
   */

  const getMetricValue = (
    record: ForecastScenarioRecord
  ): number => {

    switch (
      filters.metric
    ) {

      case "burn":
        return Number(
          record.Input || 0
        );

      case "supply":
        return Number(
          record.Replenishment ||
          0
        );

      case "stockpile":
        return Number(
          record.Stockpile || 0
        );

      default:
        return Number(
          record.Input || 0
        );
    }
  };


  /*
   * ---------------------------------------------------------
   * SCENARIO DATA
   * ---------------------------------------------------------
   */

  const scenarioResponse =
    data;


  const rawRecords:
    ForecastScenarioRecord[] =
    filters.horizon === "monthly"
      ? (
          scenarioResponse?.monthly ??
          []
        )
      : (
          scenarioResponse?.daily ??
          []
        );


  /*
   * ---------------------------------------------------------
   * SELECT BASELINE + SCENARIO
   * ---------------------------------------------------------
   */

  const entityRecords =
    rawRecords.filter(
      (
        record: ForecastScenarioRecord
      ) =>
        record.entity_id ===
        filters.entityId
    );


  const baselineRecords =
    entityRecords.filter(
      (
        record: ForecastScenarioRecord
      ) =>
        record.scenario_id ===
        "actual"
    );


  const selectedScenarioRecords =
    entityRecords.filter(
      (
        record: ForecastScenarioRecord
      ) =>
        record.scenario_id ===
        getBackendScenarioId(
          filters.scenario
        )
    );


  /*
   * ---------------------------------------------------------
   * MATCH RECORDS BY DATE
   * ---------------------------------------------------------
   */

  const scenarioByDate =
    new Map<
      string,
      ForecastScenarioRecord
    >();

  selectedScenarioRecords.forEach(
    (
      record: ForecastScenarioRecord
    ) => {

      scenarioByDate.set(
        record.event_date,
        record
      );

    }
  );


  const chartData:
    ScenarioChartPoint[] =
    baselineRecords
      .map(
        (
          baseline:
            ForecastScenarioRecord
        ): ScenarioChartPoint | null => {

          const scenario =
            scenarioByDate.get(
              baseline.event_date
            );

          if (!scenario) {
            return null;
          }

          return {
            date:
              baseline.event_date,

            baseline:
              getMetricValue(
                baseline
              ),

            scenario:
              getMetricValue(
                scenario
              ),
          };
        }
      )
      .filter(
        (
          point:
            ScenarioChartPoint | null
        ): point is ScenarioChartPoint =>
          point !== null
      );


  /*
   * ---------------------------------------------------------
   * STATISTICS
   * ---------------------------------------------------------
   */

  const baselineValues =
    chartData.map(
      (
        point:
          ScenarioChartPoint
      ) =>
        point.baseline
    );


  const scenarioValues =
    chartData.map(
      (
        point:
          ScenarioChartPoint
      ) =>
        point.scenario
    );


  const baselineAverage =
    baselineValues.length > 0
      ? baselineValues.reduce(
          (
            sum: number,
            value: number
          ) =>
            sum + value,
          0
        ) /
        baselineValues.length
      : 0;


  const scenarioAverage =
    scenarioValues.length > 0
      ? scenarioValues.reduce(
          (
            sum: number,
            value: number
          ) =>
            sum + value,
          0
        ) /
        scenarioValues.length
      : 0;


  const scenarioDifference =
    baselineAverage !== 0
      ? (
          (
            scenarioAverage -
            baselineAverage
          ) /
          Math.abs(
            baselineAverage
          )
        ) *
        100
      : 0;


  /*
   * ---------------------------------------------------------
   * FORMATTING
   * ---------------------------------------------------------
   */

  const formatNumber = (
    value: number
  ): string => {

    return new Intl.NumberFormat(
      "en-US",
      {
        maximumFractionDigits: 1,
      }
    )
      .format(value)
      .replace(
        /,/g,
        " "
      );
  };


  const formatDate = (
    value: string
  ): string => {

    const date =
      new Date(value);

    if (
      Number.isNaN(
        date.getTime()
      )
    ) {
      return value;
    }

    return date.toLocaleDateString(
      "en-GB",
      {
        day: "2-digit",
        month: "short",
      }
    );
  };


  /*
   * ---------------------------------------------------------
   * LOADING
   * ---------------------------------------------------------
   */

  if (isLoading) {

    return (
      <Box
        sx={{
          bgcolor:
            "#FFFFFF",

          border:
            "1px solid #E3E8EF",

          borderRadius: 4,

          p: {
            xs: 2.5,
            md: 3.5,
          },

          minHeight: 520,

          boxShadow:
            "0 4px 18px rgba(23,43,77,0.04)",
        }}
      >

        <Stack
          direction="row"
          spacing={1.5}
          alignItems="center"
        >

          <Box
            sx={{
              width: 44,
              height: 44,
              borderRadius: 2.5,
              bgcolor:
                "rgba(18,100,255,0.08)",
              display:
                "flex",
              alignItems:
                "center",
              justifyContent:
                "center",
            }}
          >

            <CompareArrowsRounded
              sx={{
                color:
                  "#1264FF",
              }}
            />

          </Box>


          <Box>

            <Typography
              sx={{
                fontSize: 23,
                fontWeight: 800,
                color:
                  "#172B4D",
              }}
            >
              Scenario Comparison
            </Typography>

            <Typography
              sx={{
                color:
                  "#6B778C",
                fontSize: 13.5,
                mt: 0.5,
              }}
            >
              Loading scenario data...
            </Typography>

          </Box>

        </Stack>

      </Box>
    );
  }


  /*
   * ---------------------------------------------------------
   * ERROR / EMPTY
   * ---------------------------------------------------------
   */

  if (
    isError ||
    chartData.length === 0
  ) {

    return (
      <Box
        sx={{
          bgcolor:
            "#FFFFFF",

          border:
            "1px solid #E3E8EF",

          borderRadius: 4,

          minHeight: 520,

          display:
            "flex",

          alignItems:
            "center",

          justifyContent:
            "center",

          p: 4,

          boxShadow:
            "0 4px 18px rgba(23,43,77,0.04)",
        }}
      >

        <Stack
          spacing={1}
          alignItems="center"
          textAlign="center"
        >

          <CompareArrowsRounded
            sx={{
              fontSize: 42,
              color:
                "#9AA5B1",
            }}
          />

          <Typography
            sx={{
              fontWeight: 700,
              color:
                "#172B4D",
            }}
          >
            No scenario comparison
            available
          </Typography>

          <Typography
            sx={{
              color:
                "#6B778C",
              fontSize: 14,
              maxWidth: 420,
            }}
          >
            There is not enough matching
            baseline and scenario data
            for this selection.
          </Typography>

        </Stack>

      </Box>
    );
  }


  /*
   * ---------------------------------------------------------
   * SCENARIO LABEL
   * ---------------------------------------------------------
   */

  const selectedScenarioId =
    getBackendScenarioId(
      filters.scenario
    );


  const selectedScenarioLabel =
    getScenarioLabel(
      selectedScenarioId
    );


  /*
   * ---------------------------------------------------------
   * GRADIENT
   * ---------------------------------------------------------
   */

  const gradientId =
    `scenarioComparisonGradient-${filters.metric}`;


  /*
   * ---------------------------------------------------------
   * RENDER
   * ---------------------------------------------------------
   */

  return (
    <Box
      sx={{
        bgcolor:
          "#FFFFFF",

        border:
          "1px solid #E3E8EF",

        borderRadius: 4,

        p: {
          xs: 2.5,
          md: 3.5,
        },

        boxShadow:
          "0 4px 18px rgba(23,43,77,0.04)",

        minWidth: 0,
      }}
    >

      {/* HEADER */}

      <Stack
        direction={{
          xs: "column",
          sm: "row",
        }}
        justifyContent="space-between"
        alignItems={{
          xs: "flex-start",
          sm: "center",
        }}
        spacing={2}
      >

        <Stack
          direction="row"
          spacing={1.5}
          alignItems="center"
        >

          <Box
            sx={{
              width: 48,
              height: 48,
              borderRadius: 2.5,
              bgcolor:
                "rgba(18,100,255,0.08)",
              display:
                "flex",
              alignItems:
                "center",
              justifyContent:
                "center",
              flexShrink: 0,
            }}
          >

            <CompareArrowsRounded
              sx={{
                color:
                  "#1264FF",
                fontSize: 27,
              }}
            />

          </Box>


          <Box>

            <Typography
              sx={{
                fontSize: {
                  xs: 21,
                  md: 25,
                },

                fontWeight: 800,

                color:
                  "#172B4D",

                lineHeight: 1.2,
              }}
            >
              Scenario Comparison
            </Typography>

            <Typography
              sx={{
                color:
                  "#6B778C",

                fontSize: 14,

                mt: 0.5,
              }}
            >
              Baseline {getMetricLabel().toLowerCase()} vs{" "}
              {selectedScenarioLabel}
            </Typography>

          </Box>

        </Stack>


        <Stack
          direction="row"
          spacing={1}
          alignItems="center"
        >

          <Box
            sx={{
              display:
                "flex",
              alignItems:
                "center",
              gap: 0.8,

              px: 1.5,
              py: 0.8,

              borderRadius: 2,

              bgcolor:
                "#F4F7FF",

              border:
                "1px solid #D9E4FF",
            }}
          >

            <CalendarMonthRounded
              sx={{
                fontSize: 18,
                color:
                  "#1264FF",
              }}
            />

            <Typography
              sx={{
                fontSize: 13,
                fontWeight: 700,
                color:
                  "#172B4D",
              }}
            >
              {chartData.length}{" "}
              periods
            </Typography>

          </Box>

        </Stack>

      </Stack>


      {/* KPI ROW */}

      <Box
        sx={{
          display:
            "grid",

          gridTemplateColumns: {
            xs:
              "repeat(2, minmax(0, 1fr))",

            sm:
              "repeat(3, minmax(0, 1fr))",
          },

          gap: {
            xs: 1.5,
            md: 2,
          },

          mt: 3,
        }}
      >

        {/* BASELINE */}

        <Box
          sx={{
            bgcolor:
              "#F7F9FC",

            borderRadius: 2.5,

            p: {
              xs: 1.75,
              md: 2,
            },
          }}
        >

          <Typography
            sx={{
              color:
                "#6B778C",

              fontSize: 12,

              fontWeight: 700,

              textTransform:
                "uppercase",

              letterSpacing:
                "0.04em",
            }}
          >
            Baseline Average
          </Typography>

          <Typography
            sx={{
              mt: 0.7,

              fontSize: {
                xs: 21,
                md: 24,
              },

              fontWeight: 800,

              color:
                "#172B4D",
            }}
          >
            {formatNumber(
              baselineAverage
            )}
          </Typography>

          <Typography
            sx={{
              color:
                "#6B778C",

              fontSize: 12,
              mt: 0.2,
            }}
          >
            {getMetricUnit()}
          </Typography>

        </Box>


        {/* SCENARIO */}

        <Box
          sx={{
            bgcolor:
              "#F7F9FC",

            borderRadius: 2.5,

            p: {
              xs: 1.75,
              md: 2,
            },
          }}
        >

          <Typography
            sx={{
              color:
                "#6B778C",

              fontSize: 12,

              fontWeight: 700,

              textTransform:
                "uppercase",

              letterSpacing:
                "0.04em",
            }}
          >
            {selectedScenarioLabel}
          </Typography>

          <Typography
            sx={{
              mt: 0.7,

              fontSize: {
                xs: 21,
                md: 24,
              },

              fontWeight: 800,

              color:
                "#F57C00",
            }}
          >
            {formatNumber(
              scenarioAverage
            )}
          </Typography>

          <Typography
            sx={{
              color:
                "#6B778C",

              fontSize: 12,
              mt: 0.2,
            }}
          >
            {getMetricUnit()}
          </Typography>

        </Box>


        {/* DIFFERENCE */}

        <Box
          sx={{
            bgcolor:
              "#F7F9FC",

            borderRadius: 2.5,

            p: {
              xs: 1.75,
              md: 2,
            },

            gridColumn: {
              xs: "1 / -1",
              sm: "auto",
            },
          }}
        >

          <Typography
            sx={{
              color:
                "#6B778C",

              fontSize: 12,

              fontWeight: 700,

              textTransform:
                "uppercase",

              letterSpacing:
                "0.04em",
            }}
          >
            Scenario Impact
          </Typography>

          <Typography
            sx={{
              mt: 0.7,

              fontSize: {
                xs: 21,
                md: 24,
              },

              fontWeight: 800,

              color:
                scenarioDifference >= 0
                  ? "#2E7D32"
                  : "#C62828",
            }}
          >
            {scenarioDifference >= 0
              ? "+"
              : ""}
            {scenarioDifference.toFixed(
              1
            )}
            %
          </Typography>

          <Typography
            sx={{
              color:
                "#6B778C",

              fontSize: 12,
              mt: 0.2,
            }}
          >
            vs baseline
          </Typography>

        </Box>

      </Box>


      {/* LEGEND */}

      <Stack
        direction="row"
        spacing={2.5}
        justifyContent="center"
        sx={{
          mt: 3,
          mb: 1,
        }}
      >

        <Stack
          direction="row"
          spacing={0.8}
          alignItems="center"
        >

          <Box
            sx={{
              width: 10,
              height: 10,
              borderRadius:
                "50%",
              bgcolor:
                "#1264FF",
            }}
          />

          <Typography
            sx={{
              fontSize: 13,
              color:
                "#5E6C84",
              fontWeight: 600,
            }}
          >
            Baseline
          </Typography>

        </Stack>


        <Stack
          direction="row"
          spacing={0.8}
          alignItems="center"
        >

          <Box
            sx={{
              width: 10,
              height: 10,
              borderRadius:
                "50%",
              bgcolor:
                "#F57C00",
            }}
          />

          <Typography
            sx={{
              fontSize: 13,
              color:
                "#5E6C84",
              fontWeight: 600,
            }}
          >
            {selectedScenarioLabel}
          </Typography>

        </Stack>

      </Stack>


      {/* CHART */}

      <Box
        sx={{
          width: "100%",
          height: {
            xs: 300,
            md: 390,
          },

          mt: 1,
        }}
      >

        <ResponsiveContainer
          width="100%"
          height="100%"
        >

          <AreaChart
            data={chartData}
            margin={{
              top: 10,
              right: 12,
              left: 0,
              bottom: 0,
            }}
          >

            <defs>

              <linearGradient
                id={gradientId}
                x1="0"
                y1="0"
                x2="0"
                y2="1"
              >

                <stop
                  offset="0%"
                  stopColor="#1264FF"
                  stopOpacity={0.14}
                />

                <stop
                  offset="100%"
                  stopColor="#1264FF"
                  stopOpacity={0}
                />

              </linearGradient>

            </defs>


            <CartesianGrid
              strokeDasharray="3 7"
              stroke="#DCE4F0"
              vertical={false}
            />


            <XAxis
              dataKey="date"
              tickFormatter={
                formatDate
              }
              tick={{
                fill:
                  "#7A869A",
                fontSize: 12,
              }}
              axisLine={false}
              tickLine={false}
              minTickGap={28}
            />


            <YAxis
              tick={{
                fill:
                  "#7A869A",
                fontSize: 12,
              }}
              axisLine={false}
              tickLine={false}
              width={45}
              tickFormatter={
                (
                  value: number
                ) =>
                  formatNumber(
                    value
                  )
              }
            />


            <Tooltip
              contentStyle={{
                border:
                  "1px solid #E3E8EF",

                borderRadius: 12,

                boxShadow:
                  "0 8px 25px rgba(23,43,77,0.12)",

                padding:
                  "10px 12px",
              }}

              labelFormatter={
                (
                  label
                ) =>
                  formatDate(
                    String(label)
                  )
              }

              formatter={
                (
                  value:
                    number | string,
                  name: string
                ) => [
                  `${formatNumber(
                    Number(value)
                  )} ${getMetricUnit()}`,
                  name ===
                  "baseline"
                    ? "Baseline"
                    : selectedScenarioLabel,
                ]
              }
            />


            <Area
              type="monotone"
              dataKey="baseline"
              stroke="#1264FF"
              strokeWidth={2.5}
              fill={`url(#${gradientId})`}
              dot={false}
              activeDot={{
                r: 5,
                strokeWidth: 2,
                stroke:
                  "#FFFFFF",
              }}
            />


            <Area
              type="monotone"
              dataKey="scenario"
              stroke="#F57C00"
              strokeWidth={2.5}
              fill="transparent"
              dot={false}
              activeDot={{
                r: 5,
                strokeWidth: 2,
                stroke:
                  "#FFFFFF",
              }}
            />

          </AreaChart>

        </ResponsiveContainer>

      </Box>


      {/* FOOTER */}

      <Box
        sx={{
          mt: 2,

          pt: 2,

          borderTop:
            "1px solid #E3E8EF",

          display:
            "flex",

          justifyContent:
            "space-between",

          gap: 2,

          flexWrap:
            "wrap",
        }}
      >

        <Box>

          <Typography
            sx={{
              fontSize: 12,
              fontWeight: 700,
              color:
                "#6B778C",
              textTransform:
                "uppercase",
            }}
          >
            Baseline
          </Typography>

          <Typography
            sx={{
              fontSize: 19,
              fontWeight: 800,
              color:
                "#172B4D",
              mt: 0.3,
            }}
          >
            {formatNumber(
              Math.min(
                ...baselineValues
              )
            )}{" "}
            {getMetricUnit()}
          </Typography>

        </Box>


        <Box
          sx={{
            textAlign:
              "right",
          }}
        >

          <Typography
            sx={{
              fontSize: 12,
              fontWeight: 700,
              color:
                "#6B778C",
              textTransform:
                "uppercase",
            }}
          >
            {selectedScenarioLabel}
          </Typography>

          <Typography
            sx={{
              fontSize: 19,
              fontWeight: 800,
              color:
                "#F57C00",
              mt: 0.3,
            }}
          >
            {formatNumber(
              Math.max(
                ...scenarioValues
              )
            )}{" "}
            {getMetricUnit()}
          </Typography>

        </Box>

      </Box>

    </Box>
  );
};


/**
 * =====================================================
 * BACKEND SCENARIO MAPPING
 * =====================================================
 */

const getBackendScenarioId = (
  scenario:
    ForecastFilters["scenario"]
): string => {

  switch (scenario) {

    case "actual":
      return "actual";

    case "hotdry":
      return "weather_hot_dry";

    case "hotwet":
      return "weather_hot_wet";

    case "colddry":
      return "weather_cold_dry";

    case "coldwet":
      return "weather_cold_wet";

    default:
      return "actual";
  }
};


export default ScenarioTrendChart;
